CREATE OR REPLACE FUNCTION public.add_discovery_category(_section text,_name text,_creator uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid;BEGIN IF NOT public.account_allowed(_creator) THEN RAISE EXCEPTION 'ACCOUNT_NOT_ALLOWED';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(_creator::text,0));SELECT id INTO result FROM public.discovery_categories WHERE section=_section AND normalized_name=lower(trim(_name));IF result IS NOT NULL THEN RETURN result;END IF;IF _section NOT IN('work-wanted','work-offered','service-providers','service-wanted') AND (SELECT count(*) FROM public.discovery_categories WHERE created_by=_creator AND created_at>now()-interval '1 day')>=20 THEN RAISE EXCEPTION 'CATEGORY_LIMIT';END IF;INSERT INTO public.discovery_categories(section,name,created_by) VALUES(_section,trim(_name),_creator) ON CONFLICT(section,normalized_name) DO UPDATE SET name=discovery_categories.name RETURNING id INTO result;RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.queue_free_work_match() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sec text;cat text;place text;who uuid;eid text;src text;BEGIN
IF TG_TABLE_NAME='free_work_entries' THEN sec:=NEW.section;cat:=NEW.category;place:=NEW.area;who:=NEW.user_id;eid:=NEW.id::text;src:='entry';
INSERT INTO public.free_work_notice_queue(user_id,entry_id,source,subscription_id) SELECT NEW.user_id,r.id,r.source,NEW.id FROM public.list_free_work(public.free_work_opposite(sec),place,cat) r WHERE NOT (r.source='entry' AND EXISTS(SELECT 1 FROM public.free_work_entries WHERE id::text=r.id AND user_id=NEW.user_id)) AND NOT(r.source='post' AND EXISTS(SELECT 1 FROM public.posts WHERE id::text=r.id AND user_id=NEW.user_id)) AND NOT(r.source='provider' AND r.id=NEW.user_id::text) ORDER BY r.id LIMIT 5 ON CONFLICT DO NOTHING;
ELSIF TG_TABLE_NAME='posts' THEN IF NEW.module<>'job' OR NEW.status<>'active' OR NEW.visible_after>now() OR NEW.job_expires_at<=now() THEN RETURN NEW;END IF;sec:=CASE WHEN NEW.service_type='service' THEN CASE WHEN NEW.kind='seeker' THEN 'service-providers' ELSE 'service-wanted' END ELSE CASE WHEN NEW.kind='seeker' THEN 'work-wanted' ELSE 'work-offered' END END;cat:=coalesce(nullif(NEW.skill,''),NEW.category,NEW.title);place:=NEW.location;who:=NEW.user_id;eid:=NEW.id::text;src:='post';
ELSE IF NOT NEW.published THEN RETURN NEW;END IF;sec:='service-providers';cat:=coalesce(nullif(NEW.category,''),NEW.service);place:=NEW.town;who:=NEW.user_id;eid:=NEW.user_id::text;src:='provider';END IF;
INSERT INTO public.free_work_notice_queue(user_id,entry_id,source,subscription_id) SELECT s.user_id,eid,src,s.id FROM public.free_work_entries s WHERE s.section=public.free_work_opposite(sec) AND s.user_id<>who AND s.created_at+interval '1 month'>now() AND public.free_work_category(s.category)=public.free_work_category(cat) AND lower(trim(s.area))=lower(trim(place)) AND public.account_allowed(who) AND public.account_allowed(s.user_id) ON CONFLICT DO NOTHING;RETURN NEW;END $$;